import React, { useState, useEffect } from 'react';
import { propertyAPI } from '../services/api';
import PropertyCard from '../components/PropertyCard';
import FilterSidebar from '../components/FilterSidebar';
import { FaFilter } from 'react-icons/fa';

const PropertyListing = () => {
  const [properties, setProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    location: '',
    minPrice: 0,
    maxPrice: 2000,
    propertyType: 'all',
    bedrooms: 'any',
    amenities: [],
  });
  const [showFilters, setShowFilters] = useState(false);
  const [aiSearch, setAiSearch] = useState('');

  useEffect(() => {
    fetchProperties();
  }, [filters]);

  const fetchProperties = async () => {
    try {
      setLoading(true);
      const response = await propertyAPI.getAll(filters);
      setProperties(response.data);
    } catch (error) {
      console.error('Error fetching properties:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleAISearch = async () => {
    if (!aiSearch.trim()) return;

    try {
      setLoading(true);
      const response = await propertyAPI.searchWithAI(aiSearch);
      setProperties(response.data);
    } catch (error) {
      console.error('AI search error:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (newFilters) => {
    setFilters({ ...filters, ...newFilters });
  };

  const clearFilters = () => {
    setFilters({
      location: '',
      minPrice: 0,
      maxPrice: 2000,
      propertyType: 'all',
      bedrooms: 'any',
      amenities: [],
    });
  };

  return (
    <div className="min-h-screen bg-[#050016] text-[#f9f5ff]">
      <div className="max-w-6xl mx-auto px-4 py-8">
        {/* AI Search Bar */}
        <div className="mb-8">
          <div className="max-w-3xl mx-auto">
            <div className="flex gap-4">
              <input
                type="text"
                value={aiSearch}
                onChange={(e) => setAiSearch(e.target.value)}
                placeholder="Try: 'Neon loft with skyline view under ₹5000 in Bangalore'"
                className="flex-1 px-6 py-4 rounded-xl bg-[#050016] border border-[#4c1d95] text-[#f9f5ff] placeholder:text-[#6b21a8] focus:outline-none focus:border-[#a855ff] focus:ring-2 focus:ring-[#a855ff] shadow-[0_0_18px_rgba(56,189,248,0.25)]"
                onKeyPress={(e) => e.key === 'Enter' && handleAISearch()}
              />
              <button
                onClick={handleAISearch}
                className="bg-[#a855ff] text-black px-8 py-4 rounded-xl font-semibold hover:bg-[#c084fc] transition shadow-[0_0_22px_rgba(168,85,255,0.8)] flex items-center justify-center"
              >
                🤖 AI Search
              </button>
            </div>
            <p className="text-sm text-[#a78bfa] mt-2 text-center">
              Use natural language to let the AI find your perfect neon stay
            </p>
          </div>
        </div>

        <div className="flex gap-8">
          {/* Sidebar Filters - Desktop */}
          <aside className="hidden lg:block w-80 flex-shrink-0">
            <div className="bg-[#12002e] border border-[#2e1065] rounded-2xl p-4 shadow-[0_0_30px_rgba(168,85,255,0.25)]">
              <FilterSidebar
                filters={filters}
                onFilterChange={handleFilterChange}
                onClearFilters={clearFilters}
              />
            </div>
          </aside>

          {/* Mobile Filter Button */}
          <button
            onClick={() => setShowFilters(!showFilters)}
            className="lg:hidden fixed bottom-8 right-8 bg-[#a855ff] text-black px-6 py-3 rounded-full shadow-[0_0_25px_rgba(168,85,255,0.9)] z-40 flex items-center gap-2 font-semibold"
          >
            <FaFilter /> Filters
          </button>

          {/* Mobile Filters Modal */}
          {showFilters && (
            <div className="lg:hidden fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-end">
              <div className="bg-[#12002e] w-full rounded-t-3xl max-h-[80vh] overflow-y-auto p-6 border-t border-[#4c1d95] shadow-[0_-10px_35px_rgba(15,23,42,0.9)]">
                <div className="flex justify-between items-center mb-4">
                  <h2 className="text-2xl font-bold text-[#f9f5ff]">
                    Filters
                  </h2>
                  <button
                    onClick={() => setShowFilters(false)}
                    className="text-2xl text-[#f9f5ff] hover:text-[#a855ff] transition"
                  >
                    ×
                  </button>
                </div>
                <FilterSidebar
                  filters={filters}
                  onFilterChange={handleFilterChange}
                  onClearFilters={clearFilters}
                />
              </div>
            </div>
          )}

          {/* Property Grid */}
          <main className="flex-1">
            <div className="flex justify-between items-center mb-6">
              <div>
                <h1 className="text-3xl font-bold tracking-tight">
                  Neon Stays for You
                </h1>
                <p className="text-sm text-[#a78bfa] mt-1">
                  Tune filters, then let AI do the hard work.
                </p>
              </div>
              <p className="text-sm text-[#c4b5fd]">
                {properties.length} stays found
              </p>
            </div>

            {loading ? (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {[...Array(6)].map((_, i) => (
                  <div
                    key={i}
                    className="animate-pulse bg-[#12002e] rounded-2xl p-4 border border-[#2e1065] shadow-[0_0_25px_rgba(15,23,42,0.9)]"
                  >
                    <div className="bg-[#1e1b4b] h-64 rounded-xl mb-4" />
                    <div className="bg-[#1e1b4b] h-4 w-3/4 mb-2 rounded" />
                    <div className="bg-[#1e1b4b] h-4 w-1/2 rounded" />
                  </div>
                ))}
              </div>
            ) : properties.length === 0 ? (
              <div className="text-center py-16 bg-[#12002e] border border-[#2e1065] rounded-3xl shadow-[0_0_35px_rgba(15,23,42,0.95)]">
                <p className="text-2xl text-[#c4b5fd]">
                  No properties match these vibes
                </p>
                <button
                  onClick={clearFilters}
                  className="mt-4 text-[#a855ff] underline underline-offset-4 hover:text-[#c084fc] transition"
                >
                  Clear all filters
                </button>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {properties.map((property) => (
                  <PropertyCard key={property._id} property={property} />
                ))}
              </div>
            )}
          </main>
        </div>
      </div>
    </div>
  );
};

export default PropertyListing;
